var css=document.createElement('style');
css.textContent='.adm-lg{flex:0 0 auto;display:inline-flex;align-items:center;justify-content:center;min-width:38px;height:32px;padding:0 9px;border-radius:99px;border:1.5px solid rgba(15,110,79,.35);background:#fff;color:#0F6E4F;font:800 13px/1 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;letter-spacing:.3px;cursor:pointer;margin:0 4px;-webkit-tap-highlight-color:transparent}'+
'.adm-lg:active{transform:scale(.95)}'+
'.adm-lg.fl{position:fixed;top:12px;left:12px;z-index:9990;box-shadow:0 2px 10px rgba(0,0,0,.12)}'+
'html[dir=ltr] .adm-lg.fl{left:auto;right:12px}'+
'.adm-tip{position:fixed;z-index:99991;background:#16211B;color:#fff;font:600 13.5px/1.45 system-ui,-apple-system,Segoe UI,Roboto,sans-serif;padding:9px 12px;border-radius:12px;box-shadow:0 6px 20px rgba(0,0,0,.25);max-width:230px;direction:ltr;text-align:left}'+
'.adm-tip:before{content:"";position:absolute;top:-6px;width:12px;height:12px;background:#16211B;transform:rotate(45deg);left:var(--ax,20px)}'+
'.adm-tip b{color:#7CE0A8}.adm-tip span{display:block;direction:rtl;text-align:right;opacity:.9;margin-top:2px}';
(document.head||document.documentElement).appendChild(css);
function mkBtn(fl){var b=document.createElement('button');b.type='button';b.className='adm-lg'+(fl?' fl':'');b.setAttribute('data-adm-lg','1');
  b.textContent=L==='fr'?'ع':'FR';b.setAttribute('aria-label',L==='fr'?'العربية':'Français');
  b.onclick=function(ev){ev.preventDefault();ev.stopPropagation();setLang(L==='fr'?'ar':'fr')};return b}
var tipDone=false;try{tipDone=!!localStorage.getItem('adm-lang-tip')}catch(e){}
function tip(btn){if(tipDone||L==='fr')return;tipDone=true;try{localStorage.setItem('adm-lang-tip','1')}catch(e){}
  setTimeout(function(){try{if(!btn.isConnected)return;var r=btn.getBoundingClientRect(),t=document.createElement('div');t.className='adm-tip';
    t.innerHTML='<b>Français ?</b> Appuyez sur FR<span>تحب بالفرنسية؟ اضغط على FR</span>';t.setAttribute('data-noi18n','1');document.body.appendChild(t);
    var w=230,x=Math.min(Math.max(8,r.left+r.width/2-w/2),innerWidth-w-8);t.style.left=x+'px';t.style.top=(r.bottom+10)+'px';t.style.setProperty('--ax',(r.left+r.width/2-x-6)+'px');
    var rm=function(){t.remove();document.removeEventListener('click',rm,true)};setTimeout(rm,7000);document.addEventListener('click',rm,true)}catch(e){}},900)}
function place(){try{
 var g=document.getElementById('gate'),gv=g&&g.isConnected&&!g.hidden&&getComputedStyle(g).display!=='none'&&getComputedStyle(g).visibility!=='hidden',fl=document.querySelector('.adm-lg.fl');
 if(gv){if(!fl){var b2=mkBtn(true);b2.setAttribute('data-noi18n','1');b2.style.zIndex='2147483000';document.body.appendChild(b2);tip(b2)}}
 else if(fl){fl.remove();var tp=document.querySelector('.adm-tip');if(tp)tp.remove()}
 var pw=document.querySelector('#view [data-act="xpwd"]'),sec=pw&&pw.closest('section');
 if(sec&&!document.querySelector('[data-adm-lgp]')){var s=document.createElement('section');s.className='panel';s.setAttribute('data-adm-lgp','1');s.setAttribute('data-noi18n','1');
  s.innerHTML='<h3>🌐 اللغة · Langue</h3><div class="acts" style="margin-top:8px"><button type="button" class="btn'+(L==='ar'?' primary':'')+'" data-l="ar">العربية</button><button type="button" class="btn'+(L==='fr'?' primary':'')+'" data-l="fr">Français</button></div>';
  s.addEventListener('click',function(ev){var b=ev.target.closest('[data-l]');if(!b)return;ev.preventDefault();ev.stopPropagation();if(b.getAttribute('data-l')!==L)setLang(b.getAttribute('data-l'))},true);
  sec.parentNode.insertBefore(s,sec)}
}catch(e){}}
var pmo=new MutationObserver(function(){place()});
function pst(){place();pmo.observe(document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden']})}
if(document.body)pst();else document.addEventListener('DOMContentLoaded',pst);


