var keys=Object.keys(DICT).filter(function(k){return k.length>=8&&/[\s☀-➿\uD83C-\uDBFF]/.test(k)}).sort(function(a,b){return b.length-a.length});
var tokRe=Object.keys(TOK).map(function(k){return [new RegExp('(^|[\\s\\d\\u00a0()\\[\\].,:;/+-])'+k+'(?=$|[\\s\\d\\u00a0()\\[\\].,:;?!؟،/+-])','g'),TOK[k]]});
var brandRe=BRAND.length?new RegExp('(^|[^\\u2068])('+BRAND.join('|')+')','g'):null;
function iso(o){return brandRe?o.replace(brandRe,function(a,p1,b){return p1+'\u2068'+b+'\u2069'}):o}
function tr(s){if(!s||!AR.test(s))return s;var m=/^(\s*)([\s\S]*?)(\s*)$/.exec(s),core=m[2];
  if(DICT.hasOwnProperty(core))return m[1]+iso(DICT[core])+m[3];
  var o=core;for(var i=0;i<keys.length;i++){if(o.indexOf(keys[i])>=0)o=o.split(keys[i]).join(DICT[keys[i]])}
  if(AR.test(o)){for(var j=0;j<tokRe.length;j++)o=o.replace(tokRe[j][0],function(a,p){return p+tokRe[j][1]})}
  if(AR.test(o)&&DICT.hasOwnProperty(o.trim()))o=DICT[o.trim()];
  o=iso(o);
  o=o.replace(/؟/g,'?').replace(/،/g,',').replace(/«\s*/g,'« ').replace(/\s*»/g,' »');
  return m[1]+o+m[3]}
window.ADMLang.tr=tr;
function trIn(p,v){try{for(var i=0;i<CTX.length;i++){if(p&&p.closest&&p.closest(CTX[i][0])){var m=/^(\s*)([\s\S]*?)(\s*)$/.exec(v);if(CTX[i][1].hasOwnProperty(m[2]))return m[1]+CTX[i][1][m[2]]+m[3]}}}catch(e){}return tr(v)}
var SKIP={SCRIPT:1,STYLE:1,TEXTAREA:1,INPUT:1,SELECT:1,OPTION:0,NOSCRIPT:1};
function doNode(n){if(n.nodeType===3){var p=n.parentNode;if(!p||SKIP[p.nodeName]||(p.closest&&p.closest(NOI)))return;var v=n.nodeValue;if(AR.test(v)){var t=trIn(p,v);if(t!==v)n.nodeValue=t}return}
  if(n.nodeType!==1||SKIP[n.nodeName]&&n.nodeName!=='INPUT'&&n.nodeName!=='TEXTAREA'&&n.nodeName!=='SELECT')return;
  if(n.closest&&n.closest(NOI))return;
  ['placeholder','title','aria-label','data-label'].forEach(function(a){var v=n.getAttribute&&n.getAttribute(a);if(v&&AR.test(v)){var t=trIn(n,v);if(t!==v)n.setAttribute(a,t)}});
  if((n.nodeName==='INPUT'&&/^(button|submit)$/i.test(n.type))&&AR.test(n.value))n.value=tr(n.value);
  if(n.nodeName==='SELECT'){for(var oi=0;oi<n.options.length;oi++){var op=n.options[oi],ot=op.text;if(AR.test(ot)){if(!op.hasAttribute('value'))op.setAttribute('value',ot);var tt=trIn(op,ot);if(tt!==ot)op.text=tt}}return}
  if(SKIP[n.nodeName])return;
  var c=n.firstChild;while(c){var nx=c.nextSibling;doNode(c);c=nx}}
function all(){try{doNode(document.body);if(AR.test(document.title))document.title=tr(document.title)}catch(e){}}
var busy=false;
var mo=new MutationObserver(function(ms){if(busy)return;busy=true;try{for(var i=0;i<ms.length;i++){var m=ms[i];
  if(m.type==='characterData')doNode(m.target);
  else if(m.type==='attributes')doNode(m.target);
  else for(var j=0;j<m.addedNodes.length;j++)doNode(m.addedNodes[j])}}catch(e){}busy=false});
function start(){all();mo.observe(document.body,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['placeholder','title','aria-label','data-label']})}
if(document.body)start();else document.addEventListener('DOMContentLoaded',start);
/* fenêtres natives */
['alert','confirm','prompt'].forEach(function(f){var o=window[f];if(!o)return;window[f]=function(msg){var a=[].slice.call(arguments);if(typeof msg==='string')a[0]=tr(msg);return o.apply(window,a)}});
